    /** The grades of the sheet: A, B, C and those added, in alphabetical order. */
    public List<String> gradeList() {
        List<String> all = new ArrayList<>(BASE_GRADES);
        if (addedGrades != null) {
            all.addAll(List.of(addedGrades.split(",")));
        }
        all.sort(Comparator.naturalOrder());
        return all;
    }

    public boolean isGrade(String grade) {
        return gradeList().contains(grade);
    }

    /** Add the grade (already a grade, nothing changes). */
    public void addGrade(String grade) {
        if (!isGrade(grade)) {
            List<String> added = new ArrayList<>(addedGrades == null ? List.of() : List.of(addedGrades.split(",")));
            added.add(grade);
            added.sort(Comparator.naturalOrder());
            addedGrades = String.join(",", added);
        }
    }

    /** The grades retired, in A, B, C order; empty for none. */
    public List<String> retiredGradeList() {
        return retiredGrades == null ? List.of() : List.of(retiredGrades.split(","));
    }

    public boolean isRetiredGrade(String grade) {
        return retiredGradeList().contains(grade);
    }

    /** Retire the grade (already retired, nothing changes). */
    public void retireGrade(String grade) {
        if (!isRetiredGrade(grade)) {
            List<String> all = new ArrayList<>(retiredGradeList());
            all.add(grade);
            all.sort(Comparator.naturalOrder());
            retiredGrades = String.join(",", all);
        }
    }

    public void setDefaultGrade(String defaultGrade) {
        this.defaultGrade = defaultGrade;
    }

